package cn.ksmcbrigade.mb.datagen;

import net.fabricmc.fabric.api.datagen.v1.DataGeneratorEntrypoint;
import net.fabricmc.fabric.api.datagen.v1.FabricDataGenerator;

/**
 * Registers every data provider. All mod resources that can be derived from code (recipes,
 * item models, item definitions and both language files) are generated by {@code runDatagen}.
 */
public class MsgBoardDataGen implements DataGeneratorEntrypoint {

    @Override
    public void onInitializeDataGenerator(FabricDataGenerator generator) {
        FabricDataGenerator.Pack pack = generator.createPack();

        pack.addProvider(MsgBoardRecipeProvider::new);
        pack.addProvider(MsgBoardLangProvider::english);
        pack.addProvider(MsgBoardLangProvider::chinese);
        pack.addProvider(ItemAssetProvider::new);
    }
}
